mapper.select:
SELECT id
FROM meals
WHERE user_id = #{userId}
  AND meal_type = #{mealType}
  AND meal_date = #{mealDate}

mapper.delete:
DELETE FROM meals
WHERE id = #{mealId}
  AND user_id = #{userId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM foods
    WHERE id = #{foodId}
)

SELECT id AS food_id, source_key, name AS food_name, brand, serving_description, serving_size, serving_unit, calories, carbohydrate, protein, fat FROM foods WHERE source_key IN
#{sourceKey}
ORDER BY source_key, serving_size NULLS LAST, serving_unit NULLS LAST, serving_description NULLS LAST, id

SELECT id AS food_id, source_key, name AS food_name, brand, serving_description, serving_size, serving_unit, calories, carbohydrate, protein, fat FROM foods WHERE
( name ILIKE CONCAT('%', #{token.value}, '%') OR COALESCE(brand, '') ILIKE CONCAT('%', #{token.value}, '%') OR REGEXP_REPLACE(name, '\s+', '', 'g') ILIKE CONCAT('%', #{token.compactValue}, '%') OR REGEXP_REPLACE(COALESCE(brand, ''), '\s+', '', 'g') ILIKE CONCAT('%', #{token.compactValue}, '%') )
ORDER BY CASE WHEN name = #{query} THEN 0 WHEN name ILIKE CONCAT(#{query}, '%') THEN 1 WHEN COALESCE(brand, '') = #{query} THEN 2 WHEN COALESCE(brand, '') ILIKE CONCAT(#{query}, '%') THEN 3 ELSE 4 END, name, brand LIMIT #{limit}
